import { forwardRef, useEffect, useId, useRef } from 'react';
import type {
  Ref,
  InputHTMLAttributes,
  SelectHTMLAttributes,
  TextareaHTMLAttributes,
  ReactNode,
} from 'react';
import { cx } from '@/lib/cx';
import './field.css';

/**
 * B11 · Forms. Label above field, always — placeholder is NEVER a
 * substitute for the label. Errors state what and how to fix.
 * Validation timing: on blur, then on change after first error.
 */

interface FieldChromeProps {
  label: string;
  hint?: string;
  /** Error text: what went wrong and how to fix it. Sets aria-invalid + describedby. */
  error?: string;
  required?: boolean;
}

function useFieldIds(explicit?: string) {
  const auto = useId();
  const id = explicit ?? auto;
  return { id, hintId: `${id}-hint`, errorId: `${id}-error` };
}

function FieldLabel({ id, label, required, hint, hintId }: { id: string; label: string; required?: boolean; hint?: string; hintId: string }) {
  return (
    <>
      <label className="sv-field__label" htmlFor={id}>
        {label}
        {required && (
          <span className="sv-field__req sv-mono" aria-hidden="true">
            *
          </span>
        )}
      </label>
      {hint && (
        <p className="sv-field__hint" id={hintId}>
          {hint}
        </p>
      )}
    </>
  );
}

function FieldError({ error, errorId }: { error?: string; errorId: string }) {
  if (!error) return null;
  return (
    <p className="sv-field__error" id={errorId}>
      {error}
    </p>
  );
}

/* ---------- Field (text input / textarea) ---------- */

export type FieldProps = FieldChromeProps &
  InputHTMLAttributes<HTMLInputElement> & { multiline?: false };

export type TextareaFieldProps = FieldChromeProps &
  TextareaHTMLAttributes<HTMLTextAreaElement> & { multiline: true };

/**
 * `multiline` was typed since v0.1 and never rendered — the component always
 * drew an <input>, so every "B11 multiline Field" in the docs was a single
 * line. It now draws a real <textarea> with the same chrome, ids and error
 * wiring (v0.10).
 */
export const Field = forwardRef<HTMLInputElement | HTMLTextAreaElement, FieldProps | TextareaFieldProps>(function Field(
  props,
  ref,
) {
  const { label, hint, error, required, id: explicitId, className } = props;
  const { id, hintId, errorId } = useFieldIds(explicitId);
  /* A caller's own aria-describedby is MERGED, never replaced. */
  const describedBy =
    [hint ? hintId : null, error ? errorId : null, props['aria-describedby']].filter(Boolean).join(' ') || undefined;
  const shared = {
    id,
    required,
    className: cx('sv-field__input', props.multiline && 'sv-field__input--multiline', error && 'sv-field__input--error'),
    'aria-invalid': error ? true : undefined,
    'aria-describedby': describedBy,
  } as const;
  return (
    <div className={cx('sv-field', className)}>
      <FieldLabel id={id} label={label} required={required} hint={hint} hintId={hintId} />
      {props.multiline ? (
        (() => {
          const { label: _l, hint: _h, error: _e, required: _r, id: _i, className: _c, multiline: _m, ...rest } = props;
          return <textarea rows={4} {...rest} {...shared} ref={ref as Ref<HTMLTextAreaElement>} />;
        })()
      ) : (
        (() => {
          const { label: _l, hint: _h, error: _e, required: _r, id: _i, className: _c, multiline: _m, ...rest } = props;
          return <input {...rest} {...shared} ref={ref as Ref<HTMLInputElement>} />;
        })()
      )}
      <FieldError error={error} errorId={errorId} />
    </div>
  );
});

/* ---------- Select (native until a combobox is genuinely required) ---------- */

export type SelectProps = FieldChromeProps &
  SelectHTMLAttributes<HTMLSelectElement> & { children: ReactNode };

export const Select = forwardRef<HTMLSelectElement, SelectProps>(function Select(
  { label, hint, error, required, id: explicitId, className, children, ...rest },
  ref,
) {
  const { id, hintId, errorId } = useFieldIds(explicitId);
  /* A caller's own aria-describedby is MERGED, never replaced: the spread
     above used to be overwritten by this line, silently unhooking whatever
     the caller pointed at (a SettingList consequence, a FilterLine). */
  const describedBy =
    [hint ? hintId : null, error ? errorId : null, rest['aria-describedby']].filter(Boolean).join(' ') || undefined;
  return (
    <div className={cx('sv-field', className)}>
      <FieldLabel id={id} label={label} required={required} hint={hint} hintId={hintId} />
      <span className="sv-field__selectwrap">
        <select
          {...rest}
          ref={ref}
          id={id}
          required={required}
          className={cx('sv-field__input', 'sv-field__select', error && 'sv-field__input--error')}
          aria-invalid={error ? true : undefined}
          aria-describedby={describedBy}
        >
          {children}
        </select>
        <span className="sv-field__chevron" aria-hidden="true" />
      </span>
      <FieldError error={error} errorId={errorId} />
    </div>
  );
});

/* ---------- Checkbox / Radio ---------- */

export interface CheckboxProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
  /**
   * B11 amendment (v0.10) · the mixed state — "some of the rows below are
   * on". A DOM property, not an attribute, so it is set on the node; the
   * browser then reports `aria-checked="mixed"` itself. The select-all box
   * over a partly selected table, and the parent row of a permission set.
   */
  indeterminate?: boolean;
}

export const Checkbox = forwardRef<HTMLInputElement, CheckboxProps>(function Checkbox(
  { label, className, indeterminate = false, ...rest },
  ref,
) {
  const local = useRef<HTMLInputElement | null>(null);
  useEffect(() => {
    if (local.current) local.current.indeterminate = indeterminate;
  }, [indeterminate]);
  return (
    <label className={cx('sv-check', className)}>
      <input
        {...rest}
        ref={(node) => {
          local.current = node;
          if (typeof ref === 'function') ref(node);
          else if (ref) ref.current = node;
        }}
        type="checkbox"
        className="sv-check__input"
      />
      <span className="sv-check__box" aria-hidden="true">
        <svg className="sv-check__tick" viewBox="0 0 10 8" width="10" height="8">
          <path d="M1 4l2.5 2.5L9 1" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" />
        </svg>
        <span className="sv-check__dash" />
      </span>
      <span className="sv-check__label">{label}</span>
    </label>
  );
});

export interface RadioProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
}

export const Radio = forwardRef<HTMLInputElement, RadioProps>(function Radio(
  { label, className, ...rest },
  ref,
) {
  return (
    <label className={cx('sv-check sv-check--radio', className)}>
      <input {...rest} ref={ref} type="radio" className="sv-check__input" />
      <span className="sv-check__box" aria-hidden="true">
        <span className="sv-check__dot" />
      </span>
      <span className="sv-check__label">{label}</span>
    </label>
  );
});

/* ---------- Toggle (instant-effect settings ONLY) ---------- */

export interface ToggleProps extends InputHTMLAttributes<HTMLInputElement> {
  label: string;
}

/** Anything that needs "Save" is a Checkbox, not a Toggle (B11). */
export const Toggle = forwardRef<HTMLInputElement, ToggleProps>(function Toggle(
  { label, className, ...rest },
  ref,
) {
  return (
    <label className={cx('sv-toggle', className)}>
      <input {...rest} ref={ref} type="checkbox" role="switch" className="sv-toggle__input" />
      <span className="sv-toggle__track" aria-hidden="true">
        <span className="sv-toggle__thumb" />
      </span>
      <span className="sv-check__label">{label}</span>
    </label>
  );
});

/* B11 · Forms */

@layer sv-components {
  .sv-field {
    display: flex;
    flex-direction: column;
    gap: var(--sv-s1);
  }

  .sv-field__label {
    font-size: 12px;
    font-weight: 600;
    color: var(--sv-ink);
  }

  .sv-field__req {
    margin-inline-start: var(--sv-s1);
    color: var(--sv-ink-soft);
  }

  .sv-field__hint {
    font-size: 11.5px;
    color: var(--sv-ink-soft);
  }

  .sv-field__input {
    min-height: var(--sv-control-min);
    padding: var(--sv-control-y) 12px;
    background: var(--sv-paper);
    border: 1px solid var(--sv-field-line);
    border-radius: var(--sv-r);
    font-size: var(--sv-body-size);
    font-weight: 500;
    color: var(--sv-ink);
    transition: border-color var(--sv-t-fast);
  }

  /* A textarea grows downward only — a sideways resize breaks the measure. */
  .sv-field__input--multiline {
    min-height: 88px;
    resize: vertical;
    line-height: 1.5;
  }

  /* --sv-ink-soft, never faint: faint is 2.6:1 and a placeholder is text
     the reader must read (C2). It still never replaces the label. */
  .sv-field__input::placeholder {
    color: var(--sv-ink-soft);
  }

  /* Focus: 1.5px seed border, no glow rings. */
  .sv-field__input:focus-visible {
    outline: none;
    border-color: var(--sv-seed-line);
    box-shadow: inset 0 0 0 0.5px var(--sv-seed);
  }

  .sv-field__input--error {
    border-color: var(--sv-bad);
  }

  .sv-field__input:disabled {
    background: var(--sv-wall);
    cursor: not-allowed;
  }

  .sv-field__error {
    font-size: 11.5px;
    color: var(--sv-bad);
  }

  .sv-field__selectwrap {
    position: relative;
    display: flex;
  }

  .sv-field__select {
    appearance: none;
    width: 100%;
    padding-inline-end: var(--sv-s7);
  }

  /* Chevron drawn from tokens — no color literals outside tokens.css (A1). */
  .sv-field__chevron {
    position: absolute;
    inset-inline-end: 13px;
    top: 50%;
    width: 7px;
    height: 7px;
    border-right: 1.5px solid var(--sv-ink-soft); /* rule 21: chevron glyph, points down in both directions */
    border-bottom: 1.5px solid var(--sv-ink-soft);
    transform: translateY(-70%) rotate(45deg);
    pointer-events: none;
  }

  /* ---- Checkbox / Radio ---- */

  .sv-check {
    display: inline-flex;
    align-items: center;
    gap: var(--sv-s2);
    cursor: pointer;
  }

  .sv-check__input {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
  }

  .sv-check__box {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    border: 1.5px solid var(--sv-ink-soft);
    border-radius: var(--sv-r);
    background: var(--sv-paper);
    color: var(--sv-on-dark);
    transition: background-color var(--sv-t-fast), border-color var(--sv-t-fast);
  }

  .sv-check--radio .sv-check__box {
    border-radius: 50%;
  }

  .sv-check__box svg {
    opacity: 0;
    transition: opacity var(--sv-t-fast);
  }

  .sv-check__input:checked + .sv-check__box {
    background: var(--sv-seed);
    border-color: var(--sv-seed-line);
  }

  .sv-check__input:checked + .sv-check__box svg {
    opacity: 1;
  }

  /* The mixed state: seed fill, a 2px on-dark dash, no tick. */
  .sv-check__dash {
    position: absolute;
    width: 8px;
    height: 2px;
    background: var(--sv-on-dark);
    opacity: 0;
  }

  .sv-check__box {
    position: relative;
  }

  .sv-check__input:indeterminate + .sv-check__box {
    background: var(--sv-seed);
    border-color: var(--sv-seed-line);
  }

  .sv-check__input:indeterminate + .sv-check__box .sv-check__dash {
    opacity: 1;
  }

  .sv-check__input:indeterminate + .sv-check__box svg {
    opacity: 0;
  }

  .sv-check__dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--sv-on-dark);
    opacity: 0;
    transition: opacity var(--sv-t-fast);
  }

  .sv-check__input:checked + .sv-check__box .sv-check__dot {
    opacity: 1;
  }

  .sv-check__input:focus-visible + .sv-check__box {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: 2px;
  }

  .sv-check__label {
    font-size: 13px;
    font-weight: 500;
  }

  /* ---- Toggle ---- */

  .sv-toggle {
    display: inline-flex;
    align-items: center;
    gap: var(--sv-s2);
    cursor: pointer;
  }

  .sv-toggle__input {
    position: absolute;
    width: 1px;
    height: 1px;
    margin: -1px;
    overflow: hidden;
    clip-path: inset(50%);
  }

  /* Track radius is --sv-r, not a pill: 9999px pills are banned (A1)
     and squarer reads more serious — the 76° toggle is rectilinear. */
  .sv-toggle__track {
    display: inline-flex;
    align-items: center;
    width: 32px;
    height: 18px;
    padding: 2px;
    border-radius: var(--sv-r);
    background: var(--sv-field-line);
    transition: background-color var(--sv-t-fast);
  }

  .sv-toggle__thumb {
    width: 14px;
    height: 14px;
    border-radius: 50%;
    background: var(--sv-on-dark);
    transition: transform var(--sv-t-fast);
  }

  .sv-toggle__input:checked + .sv-toggle__track {
    background: var(--sv-seed);
  }

  .sv-toggle__input:checked + .sv-toggle__track .sv-toggle__thumb {
    transform: translateX(14px);
  }

  .sv-toggle__input:focus-visible + .sv-toggle__track {
    outline: 2px solid var(--sv-seed-line);
    outline-offset: 2px;
  }

  /* RTL · the thumb travels toward the END edge, which is leftward. */
  .sv-toggle__input:checked + .sv-toggle__track .sv-toggle__thumb:dir(rtl) {
    transform: translateX(-14px);
  }
}
